"""Hidden behavioral tests for jo: file_values. Generated by pbkit from the gold binary."""


def test_at_file(run):
    r = run(args=['program=jo', 'authors=@AUTHORS'], files={'AUTHORS': b'Jan-Piet Mens <jpmens@gmail.com>\n'})
    assert r.stdout == b'{"program":"jo","authors":"Jan-Piet Mens <jpmens@gmail.com>"}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_percent_file(run):
    r = run(args=['filename=AUTHORS', 'content=%AUTHORS'], files={'AUTHORS': b'Jan-Piet Mens <jpmens@gmail.com>\n'})
    assert r.stdout == b'{"filename":"AUTHORS","content":"SmFuLVBpZXQgTWVucyA8anBtZW5zQGdtYWlsLmNvbT4K"}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_colon_file(run):
    r = run(args=['nested=:nested.json'], files={'nested.json': b'{"field1":123,"field2":"abc"}\n'})
    assert r.stdout == b'{"nested":{"field1":123,"field2":"abc"}}\n'
    assert r.stderr == b''
    assert r.returncode == 0


